interface.definition:
if(ri!showWhen <> false,
  a!localVariables(
    /*DEFAULTS*/
    local!isSubmit: a!defaultValue(value: ri!isSubmit, default: false),
    local!align: a!defaultValue(value: ri!align, default: "END"),
    local!marginBelow: a!defaultValue(value: ri!marginBelow, default: "EVEN_LESS"),
    local!showActionClose: a!defaultValue(value: ri!showActionClose, default: false),
    local!showActionRestore: a!defaultValue(value: ri!showActionRestore, default: true),
    local!showActionMaximize: a!defaultValue(value: ri!showActionMaximize, default: false),
    local!actions: 
    if(ri!selectedAction = "CLOSE",
      {},
      reject(isnull(_),
        {
          ri!additionalActions,
          a!map(
            action: "MINIMIZE",
            label: "MINIMIZE" 
            & if(ri!selectedAction = "MINIMIZE", 
                if(a!isNullOrEmpty(ri!label), 
                  ": Already minimized", 
                  ": " & ri!label & " is already minimized"
                ), 
              ""
            ),
            icon: "compress",
            /*color: "#FDBE46",*/
            orderBy: 1,
            isDisabled: ri!selectedAction = "MINIMIZE",
            showWhen: if(local!showActionRestore, ri!selectedAction <> "MINIMIZE", true)
          ),
          a!map(
            action: "RESTORE",
            label: "RESTORE" & if(a!isNullOrEmpty(ri!label), 
            "", 
            ": " & ri!label
            ),  
            icon: "window-restore",
            /*color: "#FDBE46",*/
            orderBy: 2,
            isDisabled: a!isNullOrEmpty(ri!selectedAction),
            showWhen: 
            and(
              local!showActionRestore,
              contains({"MINIMIZE"}, ri!selectedAction)
            )
          ),
          a!map(
            action: "MAXIMIZE",
            label: "MAXIMIZE" 
            & if(ri!selectedAction = "MAXIMIZE", 
              if(a!isNullOrEmpty(ri!label), 
                ": Already maximized", 
                ": " & ri!label & " is already maximized"
              ), ""
            ), 
            icon: "window-maximize",
            /*color: "#3CCA51",*/
            orderBy: 3,
            isDisabled: ri!selectedAction = "MAXIMIZE",
            showWhen: if(local!showActionMaximize, if(local!showActionRestore, ri!selectedAction <> "MAXIMIZE", true), false)
          ),
          a!map(
            action: "RESTORE",
            label: "RESTORE" & 
            if(a!isNullOrEmpty(ri!label), 
              "", 
              ": " & ri!label
            ),  
            icon: "expand",
            color: "#3CCA51",
            orderBy: 4,
            isDisabled: a!isNullOrEmpty(ri!selectedAction),
            showWhen: 
            and(
              local!showActionRestore,
              contains({"MAXIMIZE", "CLOSE"}, ri!selectedAction)
            )
          ),
          a!map(
            action: "CLOSE",
            label: "CLOSE" & if(ri!selectedAction = "CLOSE", ": Already closed", ""), 
            icon: "window-close-o",
            color: "#FC5C58",
            orderBy: 4,
            isDisabled: ri!showActionClose = "CLOSE",
            showWhen: ri!showActionClose = true
          )
        }
      )
    ),

    /*CALC*/
    local!buttons:
    a!refreshVariable(
      refreshAlways: true,
      value: 
      #"SYSTEM_SYSRULES_forEach"(
        items: local!actions,
        expression: 
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          width: "MINIMIZE",
          tooltip: fv!item.label,
          icon: fv!item.icon,
          color: fv!item.color,
          disabled: fv!item.isDisabled,
          submit: local!isSubmit,
          loadingIndicator: true,
          style: "LINK",
          /*if(ri!selectedAction = fv!item.label,*/
            /*"LINK",*/
            /*"GHOST"*/
          /*),*/
          value: fv!item.label,
          saveInto: {
            if(ri!selectedAction = fv!item.label, 
              {
                a!save(ri!selectedAction, "")
              },
              {
                a!save(ri!selectedAction, fv!item.label)
              }
            ),
            ri!saveInto
          },
          showWhen: fv!item.showWhen
        )
      )
    ),

    /*DISPLAY*/
    #"SYSTEM_SYSRULES_ButtonArrayLayout"(
      buttons: local!buttons,
      align: local!align,
      marginBelow: ri!marginBelow
    )
  ), {}
)
